package mrpapermoon.whisper.utilsimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.withContextimport java.io.IOExceptionimport java.io.InputStreamimport java.io.PipedInputStreamimport java.io.PipedOutputStreamsuspend fun Flow<ByteArray>.asInputStream(bufferSize: Int = 64 * 1024): InputStream {	return withContext(Dispatchers.IO) {		val pipedOutputStream = PipedOutputStream()		val pipedInputStream = PipedInputStream(pipedOutputStream, bufferSize)		runCatching {			collect { bytes ->				withContext(Dispatchers.IO) {					pipedOutputStream.write(bytes)					pipedOutputStream.flush()				}			}		}			.onFailure {				if (it is IOException) {					it.printStackTrace()				} else {					throw it				}			}		pipedOutputStream.close()		pipedInputStream	}}